// ---------- Settings ----------
async function settings(ctx) {
  const c = await api("/admin/config", { fresh: true }), owner = S.me.role === "owner", ranks = S.meta?.ranks || [];
  const num = (k, l, h) => field(l, inp(k, { mode: "decimal", value: c[k] }), h);
  let adminList = ""; if (owner) { const pl = await api("/admin/players?status=approved"); adminList = html`${sec("Admins (owner only)")}<div class="card"><p class="mut sm">Admins can approve players and edit XP, stats and locks. Only the owner can change this.</p>${field("Player", raw(`<select class="input" id="admsel">${opts(pl, p => p.uid, p => `${p.displayName} · ${p.arenaId}`)}</select>`))}<div class="grid g2"><button class="btn primary" data-act="mkadmin" data-on="1">Make admin</button><button class="btn" data-act="mkadmin" data-on="0">Remove admin</button></div></div>${sec("Backup")}<div class="card"><button class="btn block" data-act="export">${ico("download")}Download data export</button><p class="mut xs" style="margin-top:8px">A private JSON file. It isn't stored anywhere. Keep it safe.</p></div>`; }
  paint(ctx, html`${sectionHead("Settings & themes")}${sec("Appearance")}<div class="card">${themePicker()}</div>${sec("Game rules")}<form data-form="config" class="card" novalidate><p class="mut sm">These change how XP, rating and ranks are calculated from now on. Use with care.</p><div class="grid g2">${num("k", "Elo K-factor")}${num("winXp", "XP for a win")}${num("drawXp", "XP for a draw")}${num("lossXp", "XP for a loss")}${num("loginXp", "Daily login XP")}${num("weeklyTarget", "Weekly challenge target")}${num("teamMax", "Max team size")}${num("levelBase", "Level base")}</div>
    <h3 style="margin:8px 0">Rank thresholds (XP)</h3><div class="grid g2">${ranks.map((r, i) => field(r.name, inp("t" + i, { mode: "numeric", value: c.thresholds[i] })))}</div>${reasonField(true, "Why are you changing the rules?")}<p class="err" role="alert" data-err></p><button class="btn primary block" type="submit">Review & save</button></form>${adminList}`, { title: "Settings" });
}
F.config = async (d, f) => {
  const c = await api("/admin/config"), body = {}; const keys = ["k", "winXp", "drawXp", "lossXp", "loginXp", "weeklyTarget", "teamMax", "levelBase"], changes = [];
  keys.forEach(k => { const v = Number(d[k]); if (!Number.isFinite(v)) throw new Error("Enter a number for every setting."); if (v !== c[k]) { body[k] = v; changes.push([k, c[k], v]); } });
  const th = c.thresholds.map((_, i) => Number(d["t" + i])); if (th.some(n => !Number.isFinite(n))) throw new Error("Rank thresholds must be numbers."); if (th.some((n, i) => n !== c.thresholds[i])) { body.thresholds = th; changes.push(["rank thresholds", c.thresholds.join(", "), th.join(", ")]); }
  if (!changes.length) throw new Error("Nothing has changed."); const reason = req3(d.reason);
  if (!(await confirmSheet({ title: "Save rule changes?", confirm: "Save", danger: true, body: html`<div class="preview stack">${changes.map(([k, a, b]) => html`<div class="sm"><span class="mut">${k}</span><br>${arrow(a, b)}</div>`)}</div><p class="mut xs">Changing thresholds changes displayed ranks from stored XP.</p>` }))) return;
  await api("/admin/config", { method: "POST", body: { ...body, reason } }); toast("Rules saved", "ok"); go();
};
A.mkadmin = async d => { const sel = $("#admsel"), name = sel.selectedOptions[0].text; if (!(await confirmSheet({ title: d.on === "1" ? "Make admin?" : "Remove admin?", body: html`<p>${name}</p>`, confirm: "Confirm", danger: d.on !== "1" }))) return; await api("/owner/admins", { method: "POST", body: { uid: sel.value, admin: d.on === "1" } }); toast("Role updated", "ok"); };
// ---------- Router ----------
export async function admin(ctx, K) {
  if (!inited) { ({ S, api, html, raw, esc, ico, avatar, badge, starsHtml, sheet, confirmSheet, toast, paint, ACT, FORMS, fmt, ago, signed, go, field, inp, empty, skelRows, skelHero, errorView, sec, tile, heroCard, statGrid, modeStats, recentList, themePicker, kdVal, kdCalc, sourceLabel, uuid, debounce, hydrate, refreshMe, ADMIN_SECTIONS, DASH, uidRow, rankName, blobs } = K); A.export = K.exportData; Object.assign(ACT, A); Object.assign(FORMS, F); inited = true; }
  const sub = ctx.path.replace(/^\/admin/, "") || "/", m = (re) => re.exec(sub);
  if (sub === "/") return overview(ctx);
  if (sub === "/menu") return menu(ctx);
  if (sub === "/pending") return pending(ctx);
  if (sub === "/players") return players(ctx);
  if (m(/^\/player\/([\w-]+)$/)) return playerDetail(ctx, m(/^\/player\/([\w-]+)$/)[1]);
  if (sub === "/xp") return xpPage(ctx);
  if (sub === "/ranks") return ranksPage(ctx);
  if (sub === "/locks") return locksPage(ctx);
  if (sub === "/activity") return activity(ctx);
  if (sub === "/matches") return matches(ctx);
  if (sub === "/settings") return settings(ctx);
  if (sub === "/tournaments" || /^\/tournaments\/[\w-]+$/.test(sub)) { tmod = tmod || (await import("/admin-tournaments.js")); return tmod.tournaments(ctx, K, sub.split("/")[2] || null); }
  location.replace("#/admin");
}
